// The icons the Windows build draws from Segoe MDL2 Assets (transport buttons, the compact player,
// close boxes) and Segoe UI Symbol (the speaker), drawn here from Microsoft's open Fluent UI System
// Icons in the same design language (fluent_icons.inc, generated by tools/make-fluent-icons.py).
// Each icon comes in several design sizes; the one nearest the pixel size is filled with the text
// stack's exact-coverage rasterizer and kept as a white texture, tinted when drawn.
#include "draw.h"
#include "raster.h"
#include "ui_internal.h"

#include <cmath>
#include <cstdlib>
#include <map>
#include <string>
#include <tuple>

namespace lx {
namespace {

#include "fluent_icons.inc"

const FluentOutline* Pick(std::string_view name, int px) {
    const FluentOutline* best = nullptr;
    for (const FluentOutline& o : kFluentOutlines) {
        if (name != o.name) continue;
        // The nearest design size; on a tie the larger, whose strokes are drawn for more pixels.
        if (!best || std::abs(o.size - px) < std::abs(best->size - px) ||
            (std::abs(o.size - px) == std::abs(best->size - px) && o.size > best->size))
            best = &o;
    }
    return best;
}

// SVG path data (absolute M L H V C Z) to an outline in 26.6 pixels, y up, `px` pixels square.
bool ToOutline(const FluentOutline& f, int px, type::Outline* out) {
    out->Clear();
    const double k = (double)px / f.size;
    const char* p = f.d;
    char cmd = 0;
    double x = 0, y = 0;
    size_t contourStart = 0;
    auto number = [&](double* v) {
        while (*p == ' ' || *p == ',') ++p;
        char* end = nullptr;
        *v = std::strtod(p, &end);
        if (end == p) return false;
        p = end;
        return true;
    };
    auto add = [&](double px_, double py_, uint8_t tag) {
        out->Add((int32_t)std::lround(px_ * k * 64), (int32_t)std::lround((px - py_ * k) * 64), tag);
    };
    auto close = [&]() {
        if (out->x.size() > contourStart) {
            // A closing point on the start is implied; drop it so the contour has no empty segment.
            const size_t last = out->x.size() - 1;
            if (last > contourStart && out->tag[last] == 1 && out->x[last] == out->x[contourStart] && out->y[last] == out->y[contourStart]) {
                out->x.pop_back(), out->y.pop_back(), out->tag.pop_back();
            }
            out->ends.push_back((uint16_t)(out->x.size() - 1));
        }
        contourStart = out->x.size();
    };
    while (*p) {
        while (*p == ' ' || *p == ',') ++p;
        if (!*p) break;
        if (std::isalpha((unsigned char)*p)) cmd = *p++;
        double a, b, c, d, e, h;
        switch (cmd) {
            case 'M':
                if (!number(&a) || !number(&b)) return false;
                close();
                x = a, y = b;
                add(x, y, 1);
                cmd = 'L';  // further pairs are lines
                break;
            case 'L':
                if (!number(&a) || !number(&b)) return false;
                x = a, y = b;
                add(x, y, 1);
                break;
            case 'H':
                if (!number(&a)) return false;
                x = a;
                add(x, y, 1);
                break;
            case 'V':
                if (!number(&a)) return false;
                y = a;
                add(x, y, 1);
                break;
            case 'C':
                if (!number(&a) || !number(&b) || !number(&c) || !number(&d) || !number(&e) || !number(&h)) return false;
                add(a, b, 2), add(c, d, 2), add(e, h, 1);
                x = e, y = h;
                break;
            case 'Z':
                close();
                break;
            default:
                return false;
        }
    }
    close();
    return !out->ends.empty();
}

struct Cached {
    SDL_Texture* texture = nullptr;
    float x = 0, y = 0, w = 0, h = 0;  // the bitmap's place in the px-square box, y down
};
std::map<std::pair<std::string, int>, Cached> g_icons;

const Cached* Get(std::string_view name, int px) {
    auto key = std::make_pair(std::string(name), px);
    if (auto it = g_icons.find(key); it != g_icons.end()) return it->second.texture ? &it->second : nullptr;
    Cached& c = g_icons[key];
    const FluentOutline* f = Pick(name, px);
    type::Outline outline;
    type::Coverage cov;
    if (!f || !ToOutline(*f, px, &outline)) return nullptr;
    type::Rasterize(outline, false, &cov);
    if (cov.width <= 0 || cov.rows <= 0) return nullptr;
    std::vector<uint32_t> pixels((size_t)cov.width * cov.rows);
    for (size_t i = 0; i < pixels.size(); ++i) pixels[i] = 0x00FFFFFFu | (uint32_t)cov.pixels[i] << 24;
    c.texture = SDL_CreateTexture(g.renderer, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STATIC, cov.width, cov.rows);
    if (!c.texture) return nullptr;
    SDL_SetTextureBlendMode(c.texture, SDL_BLENDMODE_BLEND);
    SDL_SetTextureScaleMode(c.texture, SDL_SCALEMODE_NEAREST);
    SDL_UpdateTexture(c.texture, nullptr, pixels.data(), cov.width * 4);
    c.x = (float)cov.left, c.y = (float)(px - cov.top), c.w = (float)cov.width, c.h = (float)cov.rows;
    return &c;
}

}  // namespace

bool DrawFluentIcon(std::string_view name, float cx, float cy, float px, uint32_t rgb, uint8_t alpha) {
    const int size = std::max(1, (int)std::lround(px));
    const Cached* c = Get(name, size);
    if (!c) return false;
    // The em box centred on (cx, cy) on whole pixels, as DrawText's DT_CENTER | DT_VCENTER places a glyph.
    const float ox = std::floor(cx - size / 2.0f + 0.5f), oy = std::floor(cy - size / 2.0f + 0.5f);
    // Tinted the way text is: the vertex colour times the white bitmap.
    const SDL_FColor col{((rgb >> 16) & 0xFF) / 255.0f, ((rgb >> 8) & 0xFF) / 255.0f, (rgb & 0xFF) / 255.0f, alpha / 255.0f};
    const float x0 = ox + c->x, y0 = oy + c->y, x1 = x0 + c->w, y1 = y0 + c->h;
    const SDL_Vertex v[4] = {{{x0, y0}, col, {0, 0}}, {{x1, y0}, col, {1, 0}}, {{x1, y1}, col, {1, 1}}, {{x0, y1}, col, {0, 1}}};
    const int idx[6] = {0, 1, 2, 0, 2, 3};
    return SDL_RenderGeometry(g.renderer, c->texture, v, 4, idx, 6);
}

void ReleaseIconTextures() {
    for (auto& [key, c] : g_icons)
        if (c.texture) SDL_DestroyTexture(c.texture);
    g_icons.clear();
}

}  // namespace lx
